const candidates=$json.context.candidates||[];
if(!candidates.length)return[{json:{evaluation_batch:{candidate_count:0,within_threshold_count:0,breached_count:0,data_incomplete_count:0},sla_outcome:'within_threshold',lead_id:null,sla:{eligible:false,threshold_minutes:30,elapsed_minutes:null,status:'within_threshold',breached:false},no_candidates:true}}];
const evaluations=candidates.map(c=>{const elapsed=c.minutes_since_sla_start===null?null:Number(c.minutes_since_sla_start);const status=elapsed===null?'monitoring_data_incomplete':elapsed>=30?'breached':'within_threshold';return{...c,sla:{eligible:true,threshold_minutes:30,elapsed_minutes:elapsed,status,breached:status==='breached',sla_started_at:c.sla_started_at}}});
const batch={candidate_count:evaluations.length,within_threshold_count:evaluations.filter(x=>x.sla.status==='within_threshold').length,breached_count:evaluations.filter(x=>x.sla.breached).length,data_incomplete_count:evaluations.filter(x=>x.sla.status==='monitoring_data_incomplete').length};
return evaluations.map(x=>({json:{...x,evaluation_batch:batch,sla_outcome:x.sla.status}}));

return $input.all().map(({ json }) => {
  const c = json.context || {};
  const summary = c.summary || {};

  // Build Operational Summary wraps the previous node output
  // inside `evaluation`. Some branches (such as Persist SLA Breach)
  // already return their result inside another `context`.
  const wrapped = c.evaluation || {};
  const resultContext = wrapped.context || wrapped;

  // Resolve the actual SLA evaluation regardless of branch shape.
  const evaluation = resultContext.evaluation || resultContext;
  const batch = evaluation.evaluation_batch || {};

  const action =
    resultContext.sla_action ??
    evaluation.sla_action ??
    null;

  return {
    json: {
      monitoring: {
        generated_at: new Date().toISOString(),
        workflow: 'WF08_monitoring_sla',

        summary,

        sla: {
          threshold_minutes: 30,
          candidate_count: Number(batch.candidate_count || 0),
          within_threshold_count: Number(batch.within_threshold_count || 0),
          breached_count: Number(batch.breached_count || 0),
          data_incomplete_count: Number(batch.data_incomplete_count || 0)
        },

        current_evaluation: evaluation,
        sla_action: action
      }
    }
  };
});
